struct MainObject : Object {
  const char* ruby_class_name() const override { return "MainObject"; }

  virtual BasicObject* m_run_benchmark(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    BasicObject* __anon_rest__ = args;  // *rest = whole args
    Proc* _block = block;
    Proc* __anon_block__ = block;
    return nil_instance();
    return nil_instance();
  }

  virtual BasicObject* m_thrice(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    Proc* _block = block;
    _block->m_call((new Array({(&_f_i_1)})), nullptr, nullptr);
    _block->m_call((new Array({(&_f_i_2)})), nullptr, nullptr);
    return _block->m_call((new Array({(&_f_i_3)})), nullptr, nullptr);
    return nil_instance();
  }

  virtual BasicObject* m_maybe_yield(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    BasicObject* x = array_at(args, 0);
    Proc* _block = block;
    return _block->m_call((new Array({x})), nullptr, nullptr);
    return nil_instance();
  }

  void __top_level__() {
    this->m_thrice((new Array({})), nullptr, (new Proc([&](BasicObject* arg) -> BasicObject* { BasicObject* n = arg; return (ruby_puts(n), nil_instance()); })));
    this->m_maybe_yield((new Array({(&_f_i_42)})), nullptr, (new Proc([&](BasicObject* arg) -> BasicObject* { BasicObject* x = arg; return (ruby_puts(x), nil_instance()); })));
    BasicObject* total = (&_f_i_0);
    this->m_thrice((new Array({})), nullptr, (new Proc([&](BasicObject* arg) -> BasicObject* { BasicObject* n = arg; return (total = total->m_plus((new Array({n})), nullptr, nullptr)); })));
    (ruby_puts(total), nil_instance());
  }
};

